Method.Implementation:
	#dim tSC As %Status=$$$OK
	$$$TRACE("Inside Method ProcessHttpsRequest")

	Set httprequest=##class(%Net.HttpRequest).%New()

    set mrn=pRequest.HTTPHeaders.GetAt("mrn")
	do pRequest.HTTPHeaders.RemoveAt("mrn")
	$$$TRACE("EMPI: "_mrn)
		$$$TRACE("URL: "_..Adapter.URL)
	//Set httprequest.Server = ..Adapter.HTTPServer
	Set tAdURL = ..Adapter.URL_mrn, tAdURL1=$E(tAdURL)
	//Set httprequest.Location = tAdURL
	$$$TRACE("Location: "_tAdURL)
	Set httprequest.SSLConfiguration = ..Adapter.SSLConfig
	$$$TRACE("SSL Config: "_httprequest.SSLConfiguration)
	Set httprequest.Https="1"

	Set httprequest.ContentType="application/json"	
	Do httprequest.EntityBody.Write() ;Set AtEnd=false since ..%HttpRequest.Reset() leads to EntityBody.Clear() which marks AtEnd true.
	do httprequest.EntityBody.CopyFrom(pRequest.Stream)

	set accessToken=""
	set myscopes="edit"
    set isAuth=##class(%SYS.OAuth2.AccessToken).IsAuthorized(..OAuth2ClientName,,myscopes,
                 .accessToken,.idtoken,.responseProperties,.error)

    if $isobject(error) {
       //error handling here
       $$$TRACE("IsAuthorized check failed...")
    }   
    else {
	  $$$TRACE("Returned access_token: "_accessToken)    
    }  
    if isAuth=0 {
       $$$TRACE("Get new access_token...") 
       set tSC=##class(%SYS.OAuth2.Authorization).GetAccessTokenClient(..OAuth2ClientName, myscopes,.responseProperties,.error)
       set isAuth=##class(%SYS.OAuth2.AccessToken).IsAuthorized(..OAuth2ClientName,,myscopes,
                 .accessToken,.idtoken,.responseProperties,.error)
       $$$TRACE("Returned access_token: "_accessToken)    
    }

    if $$$ISOK(tSC) {
       // AddAccessToken adds the current access token to the request.
       set sc=##class(%SYS.OAuth2.AccessToken).AddAccessToken(httprequest,"header",..Adapter.SSLConfig,..OAuth2ClientName)
	}
	$$$TRACE("LOCATION: "_httprequest.Location)  
    set status = httprequest.Put(tAdURL)

    set aToken=""
    if $$$ISERR(status) {
         do $system.OBJ.DisplayError()
         Quit status
    } else {
         set response=httprequest.HttpResponse
           do ..constructResponse(response,.jwtResponse)
           set pResponse=jwtResponse
    }        

	quit tSC

Set tSC=$$$OK
If $IsObject(pHttpResponse.Data) {
	Set tStream=pHttpResponse.Data
} Else {
	Set tStream=##class(%GlobalBinaryStream).%New()
	Set tSC=tStream.Write(pHttpResponse.Data)  Quit:$$$ISERR(tSC) tSC
}
Set pResponse=##class(EnsLib.HTTP.GenericMessage).%New(tStream,,pHttpResponse)
Do pResponse.HTTPHeaders.SetAt(pHttpResponse.StatusLine,"StatusLine")
Quit tSC
